"""Minimal dependency-free HTML dashboard utilities for week 05."""

from __future__ import annotations

from html import escape

from bdm_decision.cases.week05_statistics_dashboard import (
    DailyOperation,
    dashboard_kpis,
    load_daily_operations,
)


def _scale(value: float, low: float, high: float, size: int) -> float:
    if high == low:
        return size / 2
    return (value - low) / (high - low) * size


def _line_chart_svg(rows: list[DailyOperation], field: str, width: int = 720, height: int = 180) -> str:
    padding_left = 44
    padding_bottom = 28
    plot_width = width - padding_left - 20
    plot_height = height - 30 - padding_bottom
    values = [float(getattr(row, field)) for row in rows]
    low, high = min(values), max(values)
    if low == high:
        low -= 1
        high += 1
    points = []
    for index, row in enumerate(rows):
        x = padding_left + index / max(len(rows) - 1, 1) * plot_width
        y = 20 + plot_height - _scale(float(getattr(row, field)), low, high, plot_height)
        points.append((x, y, row.date, float(getattr(row, field))))
    polyline = " ".join(f"{x:.1f},{y:.1f}" for x, y, _, _ in points)
    circles = "\n".join(
        f'<circle cx="{x:.1f}" cy="{y:.1f}" r="3"><title>{escape(date)}: {value:.2f}</title></circle>'
        for x, y, date, value in points
    )
    return f"""
<svg viewBox="0 0 {width} {height}" role="img" aria-label="{escape(field)} trend">
  <line x1="{padding_left}" y1="{20 + plot_height}" x2="{width - 20}" y2="{20 + plot_height}" />
  <line x1="{padding_left}" y1="20" x2="{padding_left}" y2="{20 + plot_height}" />
  <polyline points="{polyline}" />
  {circles}
  <text x="{padding_left}" y="{height - 6}">{escape(rows[0].date)}</text>
  <text x="{width - 112}" y="{height - 6}">{escape(rows[-1].date)}</text>
  <text x="4" y="24">{high:.0f}</text>
  <text x="4" y="{20 + plot_height}">{low:.0f}</text>
</svg>
"""


def render_dashboard_html(rows: list[DailyOperation] | None = None) -> str:
    rows = rows or load_daily_operations()
    kpis = dashboard_kpis(rows)
    cards = [
        ("Total revenue", f"{kpis['total_revenue']:,.0f}"),
        ("On-time rate", f"{kpis['on_time_rate']:.1%}"),
        ("Avg delay days", f"{kpis['average_delay_days']:.2f}"),
        ("Latest backlog", f"{int(kpis['latest_backlog_orders'])}"),
        ("Quality issues", f"{int(kpis['quality_issue_count'])}"),
    ]
    card_html = "\n".join(
        f'<section class="metric"><span>{escape(label)}</span><strong>{escape(value)}</strong></section>'
        for label, value in cards
    )
    rows_html = "\n".join(
        "<tr>"
        f"<td>{escape(row.date)}</td>"
        f"<td>{row.revenue:,.0f}</td>"
        f"<td>{row.on_time_orders}/{row.delivered_orders}</td>"
        f"<td>{row.average_delay_days:.1f}</td>"
        f"<td>{row.backlog_orders}</td>"
        f"<td>{row.quality_issue_count}</td>"
        "</tr>"
        for row in rows
    )
    revenue_chart = _line_chart_svg(rows, "revenue")
    backlog_chart = _line_chart_svg(rows, "backlog_orders")
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <title>Week 05 Operating Dashboard</title>
  <style>
    body {{
      margin: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: #1f2933;
      background: #f5f7fa;
    }}
    main {{
      max-width: 980px;
      margin: 0 auto;
      padding: 28px;
    }}
    h1, h2 {{
      font-weight: 500;
      margin: 0 0 14px;
    }}
    .metrics {{
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 10px;
      margin: 18px 0 22px;
    }}
    .metric {{
      background: #fff;
      border: 1px solid #d9e2ec;
      border-radius: 6px;
      padding: 14px;
    }}
    .metric span {{
      display: block;
      color: #52616f;
      font-size: 13px;
    }}
    .metric strong {{
      display: block;
      margin-top: 8px;
      font-size: 24px;
      font-weight: 500;
    }}
    .panel {{
      background: #fff;
      border: 1px solid #d9e2ec;
      border-radius: 6px;
      padding: 18px;
      margin-bottom: 16px;
    }}
    svg {{
      width: 100%;
      height: auto;
    }}
    svg line {{
      stroke: #9fb3c8;
      stroke-width: 1;
    }}
    svg polyline {{
      fill: none;
      stroke: #1f6f8b;
      stroke-width: 2.4;
    }}
    svg circle {{
      fill: #b05a2a;
    }}
    svg text {{
      fill: #52616f;
      font-size: 12px;
    }}
    table {{
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
    }}
    th, td {{
      border-bottom: 1px solid #e4e7eb;
      padding: 8px;
      text-align: right;
    }}
    th:first-child, td:first-child {{
      text-align: left;
    }}
  </style>
</head>
<body>
  <main>
    <h1>Week 05 Operating Dashboard</h1>
    <p>描述统计、趋势、异常与经营沟通样例。</p>
    <section class="metrics">{card_html}</section>
    <section class="panel">
      <h2>Revenue trend</h2>
      {revenue_chart}
    </section>
    <section class="panel">
      <h2>Backlog trend</h2>
      {backlog_chart}
    </section>
    <section class="panel">
      <h2>Daily records</h2>
      <table>
        <thead>
          <tr>
            <th>Date</th><th>Revenue</th><th>On-time</th><th>Delay</th><th>Backlog</th><th>Quality issues</th>
          </tr>
        </thead>
        <tbody>{rows_html}</tbody>
      </table>
    </section>
  </main>
</body>
</html>
"""


def main() -> None:
    print(render_dashboard_html())


if __name__ == "__main__":
    main()

"""Model evaluation utilities for teaching predictive modeling.

The functions in this module intentionally use only the Python standard
library.  That keeps the week-07 examples transparent: students can inspect how
confusion matrices, log loss, ROC AUC, and calibration summaries are computed
before they move to scikit-learn.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Sequence


@dataclass(frozen=True)
class ConfusionMatrix:
    """Confusion matrix for a binary classifier with positive label 1."""

    true_positive: int
    false_positive: int
    true_negative: int
    false_negative: int

    @property
    def total(self) -> int:
        return (
            self.true_positive
            + self.false_positive
            + self.true_negative
            + self.false_negative
        )


@dataclass(frozen=True)
class ClassificationMetrics:
    """Common threshold-based classification metrics."""

    accuracy: float
    precision: float
    recall: float
    specificity: float
    f1: float


@dataclass(frozen=True)
class CalibrationBin:
    """Observed outcome rate inside a probability interval."""

    lower: float
    upper: float
    count: int
    mean_probability: float
    observed_rate: float


def confusion_matrix(
    labels: Sequence[int],
    probabilities: Sequence[float],
    threshold: float = 0.5,
) -> ConfusionMatrix:
    """Return a binary confusion matrix for predicted probabilities."""

    if len(labels) != len(probabilities):
        raise ValueError("labels and probabilities must have the same length")
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be in [0, 1]")

    tp = fp = tn = fn = 0
    for label, probability in zip(labels, probabilities):
        prediction = 1 if probability >= threshold else 0
        if label == 1 and prediction == 1:
            tp += 1
        elif label == 0 and prediction == 1:
            fp += 1
        elif label == 0 and prediction == 0:
            tn += 1
        elif label == 1 and prediction == 0:
            fn += 1
        else:
            raise ValueError("labels must be 0 or 1")
    return ConfusionMatrix(tp, fp, tn, fn)


def classification_metrics(matrix: ConfusionMatrix) -> ClassificationMetrics:
    """Compute accuracy, precision, recall, specificity, and F1."""

    accuracy = _safe_divide(matrix.true_positive + matrix.true_negative, matrix.total)
    precision = _safe_divide(matrix.true_positive, matrix.true_positive + matrix.false_positive)
    recall = _safe_divide(matrix.true_positive, matrix.true_positive + matrix.false_negative)
    specificity = _safe_divide(matrix.true_negative, matrix.true_negative + matrix.false_positive)
    f1 = _safe_divide(2 * precision * recall, precision + recall)
    return ClassificationMetrics(accuracy, precision, recall, specificity, f1)


def log_loss(labels: Sequence[int], probabilities: Sequence[float], eps: float = 1e-12) -> float:
    """Return average binary cross-entropy loss."""

    if len(labels) != len(probabilities):
        raise ValueError("labels and probabilities must have the same length")
    if not labels:
        raise ValueError("at least one observation is required")

    total = 0.0
    for label, probability in zip(labels, probabilities):
        if label not in {0, 1}:
            raise ValueError("labels must be 0 or 1")
        p = min(max(probability, eps), 1 - eps)
        total += -(label * math.log(p) + (1 - label) * math.log(1 - p))
    return total / len(labels)


def roc_auc(labels: Sequence[int], probabilities: Sequence[float]) -> float:
    """Compute ROC AUC as the probability that a positive ranks above a negative."""

    if len(labels) != len(probabilities):
        raise ValueError("labels and probabilities must have the same length")

    positives = [p for label, p in zip(labels, probabilities) if label == 1]
    negatives = [p for label, p in zip(labels, probabilities) if label == 0]
    if not positives or not negatives:
        raise ValueError("ROC AUC requires both positive and negative labels")

    wins = 0.0
    for positive in positives:
        for negative in negatives:
            if positive > negative:
                wins += 1.0
            elif positive == negative:
                wins += 0.5
    return wins / (len(positives) * len(negatives))


def calibration_table(
    labels: Sequence[int],
    probabilities: Sequence[float],
    bins: int = 5,
) -> list[CalibrationBin]:
    """Summarize predicted probability and observed rate by equal-width bins."""

    if len(labels) != len(probabilities):
        raise ValueError("labels and probabilities must have the same length")
    if bins <= 0:
        raise ValueError("bins must be positive")

    rows: list[CalibrationBin] = []
    width = 1.0 / bins
    for index in range(bins):
        lower = index * width
        upper = 1.0 if index == bins - 1 else (index + 1) * width
        bucket: list[tuple[int, float]] = []
        for label, probability in zip(labels, probabilities):
            in_last_bin = index == bins - 1 and lower <= probability <= upper
            in_regular_bin = index < bins - 1 and lower <= probability < upper
            if in_last_bin or in_regular_bin:
                bucket.append((label, probability))
        if not bucket:
            rows.append(CalibrationBin(lower, upper, 0, 0.0, 0.0))
            continue
        count = len(bucket)
        mean_probability = sum(probability for _, probability in bucket) / count
        observed_rate = sum(label for label, _ in bucket) / count
        rows.append(CalibrationBin(lower, upper, count, mean_probability, observed_rate))
    return rows


def _safe_divide(numerator: float, denominator: float) -> float:
    return numerator / denominator if denominator else 0.0

